#pragma once
// Pure engine microbenchmark: NOT an editor adapter or full-client migration.
static int runMathjaxBenchmark(QTemporaryDir& root,const QString& resources,const QString& output,const QString& version){
 QFile marker(output+"/.wiz-synthetic-mathjax-benchmark");if(!marker.open(QIODevice::ReadOnly)||marker.readAll()!="synthetic-only\n"||QGuiApplication::platformName()!="cocoa")return 4;
 QWebEngineProfile profile;profile.setCachePath(root.filePath("cache"));profile.setPersistentStoragePath(root.filePath("profile"));LocalOnly local;profile.setUrlRequestInterceptor(&local);
 QWebEngineView view;view.setAttribute(Qt::WA_DontShowOnScreen);view.resize(1000,700);auto* page=new QWebEnginePage(&profile,&view);view.setPage(page);
 const bool old=version=="2.7.8",texFont=version=="4.1.3-tex",fontOnly=texFont||version=="4.1.3-newcm";if(!old&&version!="4.1.3"&&!fontOnly)return 4;
 const QString engineVersion=old?version:"4.1.3",fontName=texFont?"mathjax-tex":"mathjax-newcm",fontDirectory=texFont?"tex-font":"newcm",fontUrl=QUrl::fromLocalFile(resources+fontDirectory).toString();
 QString config=old?QStringLiteral("window.MathJax={skipStartupTypeset:true,showMathMenu:false,messageStyle:'none',SVG:{linebreaks:{automatic:true}},TeX:{equationNumbers:{autoNumber:'AMS'}}};"):"window.MathJax={startup:{typeset:false},loader:{load:[],paths:{'"+fontName+"':"+literal(fontUrl)+"}},options:{enableMenu:false,enableSpeech:false,enableBraille:false,menuOptions:{settings:{enrich:false,speech:false,braille:false,assistiveMml:false,collapsible:false}}},svg:{fontCache:'global'},output:{font:"+literal(fontName)+",fontPath:"+literal(fontUrl)+",displayOverflow:'linebreak',linebreaks:{inline:false}},tex:{tags:'ams'}};";
 const QString url=QUrl::fromLocalFile(old?resources+"wizeditor/dependency/mathjax/MathJax.js":resources+(fontOnly?"mathjax/tex-svg-nofont.js":"mathjax/tex-svg.js")).toString()+(old?"?config=TeX-AMS-MML_SVG":"");
 QString html="<!doctype html><html><head><meta charset='utf-8'><style>body{font:16px serif;width:900px;margin:20px}#content{width:900px}</style><script>window.benchmarkBegin=performance.now();"+config+"</script>"+(old?QString("<script type='text/x-mathjax-config'>MathJax.Hub.processSectionDelay=8;</script>"):QString())+"<script src='"+url.toHtmlEscaped()+"' onload=\"(async()=>{try{if(MathJax.startup)await MathJax.startup.promise;else await new Promise(r=>MathJax.Hub.Queue(r));window.loadMs=performance.now()-benchmarkBegin;window.benchmarkReady=true;}catch(e){window.benchmarkError=String(e);}})()\"></script></head><body><div id='content'></div></body></html>";
 QFile fixture(root.filePath("benchmark.html"));if(!fixture.open(QIODevice::WriteOnly))return 5;fixture.write(html.toUtf8());fixture.close();view.show();view.load(QUrl::fromLocalFile(fixture.fileName()));
 if(!wait([&]{return js(page,"!!(window.benchmarkReady||window.benchmarkError)").toBool();},45000)||!js(page,"window.benchmarkReady&&MathJax.version==="+literal(engineVersion)).toBool()){qInfo()<<"BENCH_ERROR"<<js(page,"window.benchmarkError");return 6;}
 QJsonArray samples;bool valid=true;for(int count:{64,256})for(int sample=0;sample<(output.endsWith("probe")?1:6);++sample){QString source;for(int i=0;i<count;++i)source+="\\begin{equation}\\frac{a_{"+QString::number(i)+"}^2+b^2}{1+x}=\\int_0^1 t^2\\,dt\\label{bench:"+QString::number(i)+"}\\end{equation}\n\n";source+="See \\eqref{bench:0} and \\eqref{bench:"+QString::number(count-1)+"}.";
  const QString begin=old?"MathJax.Hub.getAllJax().forEach(j=>j.Remove());MathJax.InputJax.TeX.resetEquationNumbers();":"MathJax.typesetClear();MathJax.texReset();";
  const QString render=old?"await new Promise(resolve=>MathJax.Hub.Queue(['Typeset',MathJax.Hub,content,resolve]));":"await MathJax.typesetPromise([content]);";
  page->runJavaScript("window.sampleDone=false;(async()=>{try{"+begin+"const content=document.getElementById('content');content.textContent="+literal(source)+";const start=performance.now();"+render+"const end=performance.now();const links=[...content.querySelectorAll('a')].map(a=>a.getAttribute('href')||a.getAttributeNS('http://www.w3.org/1999/xlink','href')||a.getAttribute('data-mjx-href'));window.sampleResult={count:"+QString::number(count)+",sample:"+QString::number(sample)+",typesetMs:end-start,nodes:content.querySelectorAll('*').length,svg:content.querySelectorAll('svg').length,enrichedNodes:content.querySelectorAll('[data-semantic-type]').length,errors:content.querySelectorAll('merror,.merror,.MathJax_Error').length,links:links.length,allTargets:links.length===2&&links.every(h=>{try{return !!document.getElementById(decodeURIComponent(new URL(h,location.href).hash.slice(1)));}catch(_){return false;}})};}catch(e){window.sampleResult={error:String(e)};}window.sampleDone=true;})();");
  if(!wait([&]{return js(page,"window.sampleDone").toBool();},45000))return 7;const auto result=js(page,"window.sampleResult").toMap();const bool pass=!result.contains("error")&&result.value("errors").toInt()==0&&result.value("allTargets").toBool()&&result.value("svg").toInt()>=count+2;valid&=pass;samples.append(QJsonObject::fromVariantMap(result));qInfo().noquote()<<"BENCH_SAMPLE"<<QJsonDocument(QJsonObject::fromVariantMap(result)).toJson(QJsonDocument::Compact);
 }
 const QJsonObject report{{"accepted",valid&&local.blocked.load()==0},{"version",engineVersion},{"font",old?"v2-TeX":fontName},{"matchedNoFontBundle",fontOnly},{"loadMs",js(page,"loadMs").toDouble()},{"samples",samples},{"lastLinks",QJsonArray::fromVariantList(js(page,"[...document.querySelectorAll('#content a')].map(a=>a.outerHTML.slice(0,600))").toList())},{"lastIds",QJsonArray::fromVariantList(js(page,"[...document.querySelectorAll('#content [id]')].map(e=>e.id).filter(s=>s.includes('bench')).slice(0,6)").toList())},{"externalBlocked",local.blocked.load()},{"nativeWindowExposed",view.windowHandle()&&view.windowHandle()->isExposed()},{"scope","pure local SVG engine;not editor migration or real-client speed/memory;first sample of each size excluded from warm medians"}};
 QFile result(output+"/runtime.json");if(!result.open(QIODevice::WriteOnly|QIODevice::NewOnly))return 8;result.write(QJsonDocument(report).toJson(QJsonDocument::Indented));profile.setUrlRequestInterceptor(nullptr);return report.value("accepted").toBool()?0:9;
}
